inner="\nfrom pathlib import Path\nimport json,numpy as np,torch\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2)\nmodels=g.load_models(root,'cpu');teacher,contract,dura,boundary,feature,_,_,_=models\ncache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nfrom leo_practical.equalization import linear_filter\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\ngroups=[]\nfor role,count,initial,n in (('L_s',6300,128,1024),('U_s',56700,384,3072)):\n available=np.flatnonzero(roles==role);prior=available[np.linspace(0,count-1,initial,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(3):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=128 if role=='L_s' else 384;prior=available[np.linspace(0,len(available)-1,take,dtype=int)];available=np.setdiff1d(available,prior,assume_unique=True)\n for _ in range(2):\n  old=available[np.linspace(0,len(available)-1,n,dtype=int)];available=np.setdiff1d(available,old,assume_unique=True)\n take=64 if role=='L_s' else 192;groups.append(available[np.linspace(0,len(available)-1,take,dtype=int)])\nix=np.concatenate(groups);assert len(ix)==len(np.unique(ix))==256\nix=np.concatenate((ix[:16],ix[64:112]));assert len(ix)==len(np.unique(ix))==64\n\nscenes=('practical_low_suburban','practical_mid_urban','practical_low_urban')\nnamespace='phase1-source-convex-oracle-2026110211';factors=(.1,1.,10.,100.);views={};traces_info={};quality={}\nwith torch.no_grad():\n for view in ('clean',)+scenes:\n  if view=='clean':\n   received=np.asarray(clean[ix],dtype=np.float32);candidates=None\n  else:\n   cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect')\n   received=[];candidates=[[] for _ in range(3*len(factors))];lengths=[]\n   for j in ix:\n    pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110212,session)\n    value=np.asarray(clean[j],dtype=np.float64);signal,clean_rms=normalize_input(value[0]+1j*value[1])\n    result,meta,trace=ResidualChannel(cfg,stable_seed(2026110211,namespace,view,pid),hw).process(signal,return_traces=True)\n    assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32))\n    h=np.asarray(trace['residual_kernel'],dtype=np.complex128);lengths.append(len(h));assert len(h)<=768\n    # Privileged: undo the simulator's known AGC and residual carrier rotation,\n    # and invert its true residual FIR; IQ-image and phase noise remain.\n    t=np.arange(len(result))/cfg.fs_hz\n    y=result.astype(np.complex128)/(10**(meta['agc_gain_db']/20))*np.exp(-2j*np.pi*meta['output_frequency_hz']*t)\n    ideal,_=linear_filter(signal,h,cfg.boundary)\n    noiseless=np.asarray(trace['pre_agc_signal'])*np.exp(-2j*np.pi*meta['output_frequency_hz']*t)\n    gamma=np.vdot(ideal,noiseless)/max(float(np.vdot(ideal,ideal).real),1e-20)\n    assert abs(gamma)>1e-12\n    noise=float(meta['added_noise_variance_reference'])\n    for phase_idx,input_y in enumerate((y,y/gamma)):\n     padded=np.pad(input_y,(len(y),len(y)),mode='reflect');H=np.fft.fft(h,n=len(padded));Y=np.fft.fft(padded)\n     for k,factor in enumerate(factors):\n      z=np.fft.ifft(Y*np.conj(H)/(np.abs(H)**2+factor*noise))[len(y):2*len(y)]\n      z,_=normalize_input(z);z*=clean_rms\n      candidates[phase_idx*len(factors)+k].append(np.stack((z.real,z.imag)).astype(np.float32))\n    # Exact 256-by-256 linear operator uses the simulator's reflected\n    # prehistory. No true clean IQ appears in H; the previously defined gamma\n    # is still a privileged fit using the clean/noiseless pair.\n    n=len(y);m=len(h);idx=np.pad(np.arange(n),(m-1,0),mode='reflect')\n    columns=idx[np.arange(n)[:,None]+m-1-np.arange(m)[None,:]]\n    Hmat=np.zeros((n,n),dtype=np.complex128)\n    np.add.at(Hmat,(np.arange(n)[:,None],columns),np.broadcast_to(h,(n,m)))\n    gram=Hmat.conj().T@Hmat;eigen,V=np.linalg.eigh(gram);rhs=V.conj().T@(Hmat.conj().T@(y/gamma))\n    for k,factor in enumerate(factors):\n     reg=factor*noise/max(abs(gamma)**2,1e-20)\n     z=V@(rhs/(np.maximum(eigen,0)+reg));z,_=normalize_input(z);z*=clean_rms\n     candidates[2*len(factors)+k].append(np.stack((z.real,z.imag)).astype(np.float32))\n   received=np.stack(received);candidates=[np.stack(v) for v in candidates]\n   traces_info[view]=dict(kernel_length_min=min(lengths),kernel_length_max=max(lengths))\n  probs=[];baseline_waves=[]\n  for start in range(0,len(ix),32):\n   x=core.tensor(received[start:start+32],'cpu');anchor=dura(x);baseline_waves.append(anchor.cpu())\n   inputs=[x,anchor]+([] if candidates is None else [core.tensor(a[start:start+32],'cpu') for a in candidates])\n   probs.append(torch.stack([F.softmax(teacher.classify_features(teacher.features(z)),1) for z in inputs],1).cpu())\n  if view!='clean':\n   def to_complex(t):return torch.complex(t[:,0,:],t[:,1,:])\n   reference=to_complex(core.tensor(np.asarray(clean[ix],dtype=np.float32),'cpu'))\n   def aligned_mse(signal,target,maxshift=16):\n    crop=target[:,maxshift:-maxshift];errors=[]\n    for shift in range(-maxshift,maxshift+1):\n     seg=signal[:,maxshift+shift:signal.shape[1]-maxshift+shift]\n     gain=(seg.conj()*crop).sum(1)/seg.abs().square().sum(1).clamp_min(1e-12)\n     errors.append((gain[:,None]*seg-crop).abs().square().mean(1))\n    return torch.stack(errors,dim=1).min(dim=1).values\n   reference_mse=aligned_mse(to_complex(torch.cat(baseline_waves)),reference)\n   entry=dict(n=len(ix),dura_mean_aligned_mse=float(reference_mse.mean()),filters=[])\n   for j,candidate in enumerate(candidates):\n    mse=aligned_mse(to_complex(core.tensor(candidate,'cpu')),reference)\n    entry['filters'].append(dict(noise_multiplier=factors[j%len(factors)],oracle_phase_fit=bool(j>=len(factors)),method=('exact_reflect' if j>=2*len(factors) else 'fft_reflect_pad'),mean_aligned_mse=float(mse.mean()),better_than_dura=int((mse<reference_mse).sum())))\n   quality[view]=entry\n  views[view]=np.from_dlpack(torch.cat(probs).contiguous());print('KNOWN_CHANNEL_SOURCE_PREDICTIONS_FIXED',view,flush=True)\nprint('ALL_SOURCE_PREDICTIONS_FIXED_BEFORE_SOURCE_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[ix]=='L_s';assert np.all(labels[ix[~labeled]]==-1)\nref=views['clean'][:,0,:];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[ix],teacher_target);results=[]\nfor view in scenes:\n pred=views[view].argmax(2);baseline=pred[:,1]==target;row=dict(view=view,valid=int(valid.sum()),labeled=int((valid&labeled).sum()),pseudo=int((valid&~labeled).sum()),raw=int((valid&(pred[:,0]==target)).sum()),dura=int((valid&baseline).sum()),oracle_fixed_filters=[])\n for j in range(3*len(factors)):\n  factor=factors[j%len(factors)];right=pred[:,j+2]==target\n  row['oracle_fixed_filters'].append(dict(noise_multiplier=factor,oracle_phase_fit=bool(j>=len(factors)),method=('exact_reflect' if j>=2*len(factors) else 'fft_reflect_pad'),correct=int((valid&right).sum()),L_s_correct=int((valid&labeled&right).sum()),repairs=int((valid&~baseline&right).sum()),damages=int((valid&baseline&~right).sum())))\n results.append(row);print('KNOWN_CHANNEL_SOURCE_RESULT',json.dumps(row),flush=True)\nprint('SOURCE_KNOWN_CHANNEL_ORACLE '+json.dumps(dict(status='PRIVILEGED_SOURCE_KNOWN_CHANNEL_ORACLE',source_ids=len(ix),results=results,traces_info=traces_info,\n quality=quality,labels='L_s actual; U_s high-confidence clean-teacher pseudo-targets',U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_labels=True,\n caveat='True simulated channel kernel, residual frequency, AGC, clean-source RMS and phase fitted from clean/noiseless paired traces are privileged and unavailable at deployment. The exact reflected-boundary linear inverse remains finite and is not an upper bound. Simulator is not validated real satellite data; source experts saw source records. Previously observed Phase1 test results motivated exploration.'),ensure_ascii=False),flush=True)\n"
